-- Parameters supplied by generate.py. Every value is derived from global row n.
INSERT INTO bench.otel_logs
WITH
    number AS n,
    cityHash64(n) AS h,
    h % 100000 AS slot,
    multiIf(slot < 60000, 0, slot < 75000, 1, slot < 84000, 2,
        slot < 90000, 3, slot < 94000, 4, slot < 96500, 5,
        slot < 98000, 6, slot < 99000, 7, slot < 99500, 8,
        slot < 99700, 9, slot < 99800, 10, slot < 99860, 11,
        slot < 99900, 12, slot < 99930, 13, slot < 99950, 14,
        slot < 99965, 15, slot < 99977, 16, slot < 99987, 17,
        slot < 99995, 18, 19) AS svc,
    ['edge-gateway','checkout','payments','search','catalog','orders',
     'inventory','auth','notifications','shipping','billing','recommendations',
     'audit','scheduler','backup','cert-renewer','dns-sync','quota-cleaner',
     'report-exporter','archive-sweeper'][svc + 1] AS service,
    -- At scale 1 the last hour is 12 million rows, hot service ~2,000/s.
    least(toUInt64(12000000 * {scale:Float64}), intDiv({total:UInt64}, 2)) AS burst,
    if(n < burst,
       {end_ns:Int64} - 3600000000000 + toInt64(toFloat64(n) * 3600000000000 / greatest(burst, 1)),
       {end_ns:Int64} - {days:UInt64} * 86400000000000 +
           toInt64((toFloat64(n) - burst) * ({days:UInt64} * 86400000000000 - 3600000000000) /
                   greatest({total:UInt64} - burst, 1))) AS ts,
    lower(hex(sipHash128(n))) AS request_id,
    concat('/api/v1/', ['orders','users','cart','products','payments','health'][h % 6 + 1]) AS endpoint,
    multiIf(cityHash64(n, 'severity') % 1000 < 250, 'debug', cityHash64(n, 'severity') % 1000 < 950, 'info', cityHash64(n, 'severity') % 1000 < 990, 'warn', 'error') AS level,
    concat(toString(h % 2000 + 1), 'ms') AS duration,
    concat(toString(round((h % 10000 + 1) / 10., 1)), 'KB') AS bytes,
    toString(round((h % 10000) / 100., 2)) AS load,
    toString(if(h % 100 < 97, 200, if(h % 2 = 0, 500, 404))) AS status
SELECT
    fromUnixTimestamp64Nano(ts),
    if(h % 4 = 0, lower(hex(sipHash128(n + 17))), ''),
    if(h % 4 = 0, lower(hex(cityHash64(n + 19))), ''),
    toUInt8(h % 4 = 0), level,
    toUInt8(multiIf(level = 'debug', 5, level = 'info', 9, level = 'warn', 13, 17)),
    if(n % 3 = 2, service, concat('otel-', service)),
    multiIf(cityHash64(n, 'format') % 3 = 0,
        toJSONString(map('message', 'request completed', 'endpoint', endpoint,
            'status', status, 'duration', duration, 'bytes', bytes,
            'load', load, 'request_id', request_id)),
        cityHash64(n, 'format') % 3 = 1,
        concat('msg="request completed" endpoint=', endpoint, ' status=', status,
            ' duration=', duration, ' bytes=', bytes, ' load=', load, ' request_id=', request_id),
        concat('request ', request_id, ' completed for user ', toString(h % 100000),
            ' on ', endpoint, ' status ', status, ' in ', duration)),
    '',
    map('host.name', concat('node-', toString(h % 50)),
        'cloud.region', ['us-east-1','us-west-2','eu-west-1'][h % 3 + 1],
        'cloud.availability_zone', concat('zone-', toString(h % 3)),
        'k8s.namespace.name', ['prod','payments','platform'][svc % 3 + 1],
        'k8s.cluster.name', 'bench-cluster',
        'k8s.pod.name', concat(service, '-', toString(h % 128)),
        'k8s.container.name', service,
        'service.version', concat('1.', toString(h % 5), '.0'),
        'deployment.environment', 'production-shaped-synthetic',
        'os.type', 'linux', 'telemetry.sdk.language', 'go',
        'service.instance.id', concat(service, '-', toString(h % 32))),
    '', 'bench.generator', '1.0', map('generator', 'deterministic-numbers'),
    map('journald.CONTAINER_NAME', if(n % 3 = 0, service, ''),
        'journald._SYSTEMD_UNIT', if(n % 3 = 1, service, ''),
        'http.route', endpoint, 'http.status_code', status,
        'http.request.method', ['GET','POST','PUT','DELETE'][h % 4 + 1],
        'request.id', request_id,
        'journald.__CURSOR', concat('s=', lower(hex(cityHash64(n))), ';i=', toString(n)),
        'journald.__SEQNUM', toString(n),
        'event.timestamp', toString(fromUnixTimestamp64Nano(ts)),
        'duration', duration, 'bytes', bytes, 'load', load,
        'tenant', concat('tenant-', toString(h % 1000)),
        'user.id', toString(h % 100000),
        'network.protocol', 'http', 'retry.count', toString(h % 3),
        'cache.hit', if(h % 2 = 0, 'true', 'false'), 'synthetic', 'true')
FROM numbers({offset:UInt64}, {count:UInt64})
SETTINGS max_threads = 2, max_insert_threads = 1, max_memory_usage = 1200000000,
    max_block_size = 32768, min_insert_block_size_rows = 32768,
    min_insert_block_size_bytes = 33554432
